    EnTextos.textExporteInserteMemoriaUsb,
    'Włóż pamięć USB, przypisz nazwę do pliku docelowego, naciśnij przycisk „Eksportuj”, aby rozpocząć eksport. Plik konfiguracyjny zostanie zapisany w folderze „/ CTI / CFG /” pamięci USB.'
