    EnTextos.textMensajeVariacionDelPeso,
    'W tej opcji możemy kontrolować zmiany wagi, które tensometry silosów muszą kontrolować podczas dozowania. W parametrach wagi i czasu musimy wskazać zmianę wagi, którą w silosie musi nastąić we wskazanym czasie. Jeśli ta zmiana nie zostanie wygenerowana we wskazanym czasie, system wygeneruje alarm.'
