    'Po włączeniu tego trybu główny przekaźnik programu zostanie włączony tylko podczas godzin dozowania sterowania AUX. Przekaźnik główny zostanie podłączony w godzinach skonfigurowanych w układzie sterowania AUX w czasie wskazanym w poniższej opcji.'
